param([Parameter(Mandatory=$true)][string]$SourcePath,[Parameter(Mandatory=$true)][string]$HeaderPath,[Parameter(Mandatory=$true)][string]$TestPath,[Parameter(Mandatory=$true)][string]$HypervisorCMake,[Parameter(Mandatory=$true)][string]$TestsCMake,[Parameter(Mandatory=$true)][string]$ForbiddenPaths)
$ErrorActionPreference='Stop';function A($x,$m){if(-not $x){throw $m}};function O($t,$a,$n){$p=0;foreach($x in $a){$q=$t.IndexOf($x,$p,[StringComparison]::Ordinal);A($q-ge0)"$n $x";$p=$q+$x.Length}}
function V($s,$h,$t,$hc,$tc){foreach($x in @('VMX_CR3_ROUTE_PLAN_VERSION UINT32_C(1)','VMX_CR3_ROUTE_ACTION_WRITE_CR3_ADVANCE_RESUME','VmxCr3RoutePlanBuild(','commit Transition.Next only after both planned VMCS writes succeed','No VMREAD, VMWRITE')){A($h.Contains($x))"header $x"};foreach($x in @('sizeof(VMX_CR3_ROUTE_PLAN) == 128','offsetof(VMX_CR3_ROUTE_PLAN, Transition) == 32')){A($h.Contains($x))"ABI $x"};O $s @('GuestGprCount != VMX_CR3_EXIT_GPR_COUNT','!Zero(OutPlan, sizeof(*OutPlan))','Separate(TargetSet, sizeof(*TargetSet)','Separate(Previous, sizeof(*Previous)','Separate(GuestGprs, GprBytes','!Canonical(GuestRip)','InstructionLength == 0','InstructionLength > VMX_CR3_ROUTE_MAX_INSTRUCTION_LENGTH','GuestRip > UINT64_MAX - InstructionLength','!Canonical(AdvancedRip)','VmxCr3ExitDecode(','VmxCr3ResidencyApply(','Staged.GuestCr3 = Decision.Target.Operand','Staged.AdvancedRip = AdvancedRip','Staged.Transition = Transition','*OutPlan = Staged') 'route';A($s-notmatch '(?i)ntddk|wdm\.h|wdf\.h|__vmx|vmread|vmwrite|invept|IOCTL|Hook|VMCS_|Dispatcher')'pure';foreach($x in @('exact CR3','advanced RIP','enter','KVA stay','leave','noncanonical RIP','RIP overflow','advanced noncanonical','zero length','long length','short GPRs','stale generation','state/output alias')){A($t.Contains($x))"test $x"};A(([regex]::Matches($hc,'(?m)^\s*vmx_cr3_route_plan\.c\s*$')).Count-eq1)'source once';A(([regex]::Matches($tc,'add_test\(NAME test_vmx_cr3_route_plan COMMAND')).Count-eq1)'unit once';A(([regex]::Matches($tc,'test_vmx_cr3_route_plan_contracts')).Count-eq1)'contract once'}
$s=Get-Content -Raw $SourcePath;$h=Get-Content -Raw $HeaderPath;$t=Get-Content -Raw $TestPath;$hc=Get-Content -Raw $HypervisorCMake;$tc=Get-Content -Raw $TestsCMake;V $s $h $t $hc $tc;foreach($p in $ForbiddenPaths.Split(',')){A((Get-Content -Raw $p)-notmatch 'VmxCr3RoutePlan|vmx_cr3_route_plan')"unwired $p"};$m=@($s.Replace('GuestGprCount != VMX_CR3_EXIT_GPR_COUNT','0'),$s.Replace('!Canonical(GuestRip)','0'),$s.Replace('InstructionLength == 0','0'),$s.Replace('GuestRip > UINT64_MAX - InstructionLength','0'),$s.Replace('!Canonical(AdvancedRip)','0'),$s.Replace('VmxCr3ExitDecode(','VmxCr3TargetSelect('),$s.Replace('VmxCr3ResidencyApply(','VmxCr3ResidencyInitialize('),$s.Replace('Staged.GuestCr3 = Decision.Target.Operand','Staged.GuestCr3 = 0'),$s.Replace('*OutPlan = Staged','memset(OutPlan,0,sizeof(*OutPlan))'));$i=0;foreach($x in $m){$i++;A($x-ne$s)"vacuous $i";$bad=$false;try{V $x $h $t $hc $tc}catch{$bad=$true};A($bad)"accepted $i"};Write-Host 'PASS: pure CR3 route plan composes decode, residency, exact CR3/RIP writes, failure preservation, and remains unwired.'
